use std::collections::HashMap;
use ibis_calc::eval::Book;
use ibis_calc::CellValue;

struct DummyBook {
    cells: HashMap<(usize, u32, u32), CellValue>,
}

impl DummyBook {
    fn new() -> Self {
        let mut cells = HashMap::new();
        let sheet_d = 1;
        let b_vals = [-2.5, 0.0, 3.7, 12.0, -7.0, 100.0, 0.25, 8.0, 1e5, 42.0];
        let c_vals = ["apple", "Banana", "cherry", "date", "Elder", "fig", "grape", "", "kiwi", "lemon"];
        let j_vals = [2.1, 3.9, 6.2, 7.8, 10.1, 12.2, 13.8, 16.1, 18.0, 20.3];
        for i in 0..10 {
            // A列: 0
            cells.insert((sheet_d, i as u32, 0), CellValue::Number((i + 1) as f64));
            // B列: 1
            cells.insert((sheet_d, i as u32, 1), CellValue::Number(b_vals[i]));
            // C列: 2
            cells.insert((sheet_d, i as u32, 2), CellValue::Text(c_vals[i].into()));
            // I列: 8 (1..10)
            cells.insert((sheet_d, i as u32, 8), CellValue::Number((i + 1) as f64));
            // J列: 9
            cells.insert((sheet_d, i as u32, 9), CellValue::Number(j_vals[i]));
        }
        let e_vals: [CellValue; 10] = [
            CellValue::Bool(true),
            CellValue::Bool(false),
            CellValue::Number(1.0),
            CellValue::Text("x".into()),
            CellValue::Empty,
            CellValue::Number(2.5),
            CellValue::Text("TRUE".into()),
            CellValue::Number(0.0),
            CellValue::Number(-3.0),
            CellValue::Text("7".into()),
        ];
        for (i, v) in e_vals.into_iter().enumerate() {
            cells.insert((sheet_d, i as u32, 4), v);
        }
        // F1: #N/A, F2: #DIV/0!, F3: #VALUE!
        cells.insert((sheet_d, 0, 5), CellValue::Error(ibis_calc::value::CellError::NA));
        cells.insert((sheet_d, 1, 5), CellValue::Error(ibis_calc::value::CellError::Div0));
        cells.insert((sheet_d, 2, 5), CellValue::Error(ibis_calc::value::CellError::Value));

        Self { cells }
    }
}

impl Book for DummyBook {
    fn sheet_count(&self) -> usize { 2 }
    fn sheet_name(&self, sheet: usize) -> &str {
        if sheet == 1 { "D" } else { "Sheet1" }
    }
    fn value(&self, sheet: usize, row: u32, col: u32) -> CellValue {
        self.cells.get(&(sheet, row, col)).cloned().unwrap_or(CellValue::Empty)
    }
    fn formula(&self, _sheet: usize, _row: u32, _col: u32) -> Option<&str> { None }
    fn for_each_cell(&self, sheet: usize, area: (u32, u32, u32, u32), f: &mut dyn FnMut(u32, u32, &CellValue)) {
        let (r1, c1, r2, c2) = area;
        for r in r1..=r2 {
            for c in c1..=c2 {
                if let Some(v) = self.cells.get(&(sheet, r, c)) {
                    f(r, c, v);
                }
            }
        }
    }
    fn extent(&self, _sheet: usize) -> (u32, u32) { (100, 100) }
    fn defined_name(&self, _name: &str, _sheet: Option<usize>) -> Option<String> { None }
}

